#!/usr/bin/env python3
"""Print the next order id by incrementing the last id in ids.txt."""

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int, width: int = 4) -> str:
    """Convert an integer to a zero-padded base36 string."""
    digits = []
    for _ in range(width):
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def from_base36(s: str) -> int:
    """Convert a base36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch.upper())
    return n


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-" + to_base36(0))
        return

    if not lines:
        print("ORD-" + to_base36(0))
        return

    last_id = lines[-1]
    # Expect format ORD-XXXX
    if not last_id.startswith("ORD-") or len(last_id) != 8:
        print(f"Invalid id format: {last_id!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]
    num = from_base36(suffix) + 1
    print("ORD-" + to_base36(num))


if __name__ == "__main__":
    main()

