#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate event_ids (keep first occurrence), write deduped.jsonl."""

import json

def main() -> None:
    seen: set[str] = set()
    with open("events.jsonl", encoding="utf-8") as fin, \
         open("deduped.jsonl", "w", encoding="utf-8") as fout:
        for line in fin:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid is not None and eid not in seen:
                seen.add(eid)
                fout.write(json.dumps(event, ensure_ascii=False) + "\n")

if __name__ == "__main__":
    main()

