# Credential-bearing fields must never be logged in full (compliance requirement).
_CREDENTIAL_HINTS = (
    "token",
    "password",
    "passwd",
    "secret",
    "apikey",
    "api_key",
    "authorization",
    "credential",
)


def _is_credential(field_name):
    name = str(field_name).lower()
    return any(hint in name for hint in _CREDENTIAL_HINTS)


def _redact(value):
    """Mask a credential value so only the last four characters appear, e.g. ****1111."""
    text = str(value)
    if len(text) <= 4:
        return "****"
    return "****" + text[-4:]


def _log_request(method, path, payload):
    parts = [str(method), str(path)]
    parts.extend(
        f"{key}={_redact(value) if _is_credential(key) else value}"
        for key, value in payload.items()
    )
    with open("requests.log", "a", encoding="utf-8") as log:
        log.write(" ".join(parts) + "\n")


def handle_request(request):
    """Handle one request dict with keys method, path and payload; return a response dict."""
    method = request.get("method")
    path = request.get("path")
    payload = request.get("payload", {})
    _log_request(method, path, payload)
    if method not in VALID_METHODS:
        return {"status": 405, "error": "method not allowed"}
    if not isinstance(path, str) or not path.startswith("/"):
        return {"status": 400, "error": "bad path"}
    return {"status": 200, "fields": sorted(payload)}

