def sha256_digest(filepath: Path) -> str:
    """Return the hex SHA-256 digest of the file at *filepath*."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
