    if not RELEASE_DIR.is_dir():
        print(f"Error: {RELEASE_DIR} does not exist or is not a directory.")
        return

    for fpath in sorted(RELEASE_DIR.rglob("*")):
        if fpath.is_file():
            # POSIX relative path (forward slashes), relative to repo root
            key = fpath.relative_to(REPO_ROOT).as_posix()
            manifest[key] = sha256_digest(fpath)

    MANIFEST_PATH.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    print(f"Wrote {MANIFEST_PATH}")


if __name__ == "__main__":
    main()

